    assert(iter != kh_end(conn->streams));
    kh_del(h2o_http2_stream_t, conn->streams, iter);

    if (stream->_conn_stream_in_progress) {
        h2o_http2_conn_t *conn = (h2o_http2_conn_t *)stream->req.conn;
        stream->_conn_stream_in_progress = 0;
